def f(g):
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    C=comps(g,bg)
    cc=Counter(c for c,_ in C)
    key=[k for k in range(len(C)) if cc[C[k][0]]==1][0]
    keyobj=C[key]
    # group comps by shape; find the shape that appears twice
    shapes={}
    for kk,c,nm in C: shapes.setdefault(normshape(nm),[]).append(kk)
    for sh,members in shapes.items():
        if len(members)==2:
            a,b=members
            dA=dB=mindist_cells(set(keyobj[1]),{nm_ for nm_,_ in C}[min(100,min((abs(ap-ak)+abs(bp-bk) for ap,bp in C[a][1] for ak,bk in keyobj[1])))] ) if False else None
            dA=mindist_cells({C[a][1]}, set(keyobj[1])); dB=mindist_cells({C[b][1]},set(keyobj[1]))
            # recolor the one FARTHER from key
            if dA>=dB:
                for i,j in C[a][1]: g[i][j]=C[key][0]
            else:
                for i,j in C[b][1]: g[i][j]=C[key][0]
            break
    return g

